assert len(ROWS) == 124, f"Expected 124 questions, got {len(ROWS)}"
questions = []
for index, (category, prompt, options, answer, explanation) in enumerate(ROWS, 1):
    questions.append({
        "id": f"{category}.{index:03d}",
        "category": category,
        "prompt": prompt,
        "options": options,
        "answerIndex": answer,
        "explanation": explanation,
    })

output = Path(__file__).resolve().parents[1] / "app/src/main/assets/questions.json"
output.write_text(json.dumps({"schemaVersion": 1, "questions": questions}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"Wrote {len(questions)} questions to {output}")
